insert into public.questions (category, difficulty, question, options, correct_index, explanation, tradition, valid_as_of, source) values
  ('anime', 'easy', 'In "Naruto", which hidden village is Naruto Uzumaki from?', '["Hidden Sand Village","Hidden Mist Village","Hidden Leaf Village (Konoha)","Hidden Cloud Village"]'::jsonb, 2, 'Naruto is a ninja of Konohagakure, the Village Hidden in the Leaves.', null, null, null),
  ('anime', 'easy', 'In "One Piece", what is the name of Monkey D. Luffy''s crew?', '["Red Hair Pirates","Whitebeard Pirates","Straw Hat Pirates","Heart Pirates"]'::jsonb, 2, 'Luffy captains the Straw Hat Pirates, named after his signature straw hat.', null, null, null),
  ('anime', 'easy', 'Which animation studio produced "Spirited Away" (2001)?', '["Toei Animation","Studio Ghibli","Madhouse","Kyoto Animation"]'::jsonb, 1, 'Spirited Away was directed by Hayao Miyazaki at Studio Ghibli and won the Academy Award for Best Animated Feature.', null, null, null),
  ('anime', 'medium', 'In "Dragon Ball", what is Goku''s Saiyan birth name?', '["Kakarot","Raditz","Bardock","Tarble"]'::jsonb, 0, 'Goku was born Kakarot. Raditz is his brother and Bardock his father.', null, null, null),
  ('anime', 'medium', 'In "Attack on Titan", which is the outermost of the three main walls protecting humanity?', '["Wall Rose","Wall Sina","Wall Maria","Wall Eldia"]'::jsonb, 2, 'From outermost to innermost the walls are Maria, Rose and Sina.', null, null, null),
  ('anime', 'medium', 'In "Death Note", which Shinigami drops the Death Note into the human world?', '["Ryuk","Rem","Sidoh","Gelus"]'::jsonb, 0, 'Ryuk drops his notebook out of boredom, and Light Yagami finds it.', null, null, null),
  ('anime', 'medium', 'In "Demon Slayer", which breathing style does Tanjiro first learn from Sakonji Urokodaki?', '["Water Breathing","Flame Breathing","Thunder Breathing","Beast Breathing"]'::jsonb, 0, 'Urokodaki trains Tanjiro in Water Breathing; he later also uses Sun Breathing (Hinokami Kagura).', null, null, null),
  ('anime', 'hard', 'In "Fullmetal Alchemist", what is the fundamental law of alchemy called?', '["Equivalent Exchange","Conservation of Souls","The Truth Principle","Transmutation Balance"]'::jsonb, 0, 'Equivalent Exchange states that to obtain something, something of equal value must be lost.', null, null, null),
  ('anime', 'hard', 'Who created the "Dragon Ball" manga?', '["Eiichiro Oda","Akira Toriyama","Masashi Kishimoto","Tite Kubo"]'::jsonb, 1, 'Akira Toriyama created Dragon Ball. Oda created One Piece, Kishimoto Naruto and Kubo Bleach.', null, null, null),
  ('general_knowledge', 'easy', 'How many days are there in a leap year?', '["365","364","367","366"]'::jsonb, 3, 'A leap year adds 29 February, giving 366 days.', null, null, null),
  ('general_knowledge', 'easy', 'Which colour is produced by mixing blue and yellow paint?', '["Purple","Green","Orange","Brown"]'::jsonb, 1, 'In subtractive (paint) colour mixing, blue and yellow make green.', null, null, null),
  ('general_knowledge', 'easy', 'What is the official currency of Japan?', '["Yen","Won","Yuan","Ringgit"]'::jsonb, 0, 'Japan uses the yen. The won is Korean, the yuan Chinese and the ringgit Malaysian.', null, null, null),
  ('general_knowledge', 'medium', 'Which organ in the human body produces the hormone insulin?', '["Liver","Pancreas","Kidney","Spleen"]'::jsonb, 1, 'Beta cells in the pancreatic islets of Langerhans produce insulin.', null, null, null),
  ('general_knowledge', 'medium', 'Which naturally occurring material is the hardest on the Mohs scale?', '["Quartz","Diamond","Topaz","Corundum"]'::jsonb, 1, 'Diamond ranks 10 on the Mohs hardness scale, the maximum.', null, null, null),
  ('general_knowledge', 'medium', 'In which city is the ancient Colosseum located?', '["Athens","Naples","Rome","Istanbul"]'::jsonb, 2, 'The Flavian Amphitheatre, known as the Colosseum, stands in the centre of Rome.', null, null, null),
  ('general_knowledge', 'medium', 'How many keys does a standard modern piano have?', '["88","76","72","96"]'::jsonb, 0, 'A standard modern piano has 88 keys: 52 white and 36 black.', null, null, null),
  ('general_knowledge', 'hard', 'How many bones does a typical adult human skeleton have?', '["208","196","206","212"]'::jsonb, 2, 'The typical adult skeleton has 206 bones; infants have more, which fuse during growth.', null, null, null),
  ('geography', 'easy', 'What is the capital city of Australia?', '["Sydney","Canberra","Melbourne","Perth"]'::jsonb, 1, 'Canberra was purpose-built as the capital as a compromise between Sydney and Melbourne.', null, null, null),
  ('geography', 'easy', 'Which is the largest ocean on Earth?', '["Atlantic Ocean","Pacific Ocean","Indian Ocean","Arctic Ocean"]'::jsonb, 1, 'The Pacific covers roughly a third of Earth''s surface.', null, null, null),
  ('geography', 'medium', 'Which river flows through Cairo?', '["Euphrates","Nile","Tigris","Congo"]'::jsonb, 1, 'Cairo lies on the banks of the Nile, just south of the Nile Delta.', null, null, null),
  ('geography', 'medium', 'Mount Everest lies on the border between Nepal and which country?', '["India","Bhutan","China","Pakistan"]'::jsonb, 2, 'Everest''s summit sits on the border of Nepal and the Tibet Autonomous Region of China.', null, null, null),
  ('geography', 'medium', 'What is the largest hot desert in the world?', '["Arabian Desert","Gobi","Kalahari","Sahara"]'::jsonb, 3, 'The Sahara is the largest hot desert. Antarctica is the largest desert overall (a cold desert).', null, null, null),
  ('geography', 'medium', 'What is the smallest country in the world by area?', '["Monaco","San Marino","Vatican City","Liechtenstein"]'::jsonb, 2, 'Vatican City covers about 0.44 km², making it the smallest sovereign state.', null, null, null),
  ('geography', 'hard', 'Lake Baikal, the world''s deepest lake, is located in which country?', '["Mongolia","Kazakhstan","China","Russia"]'::jsonb, 3, 'Lake Baikal in Siberia, Russia, is over 1,600 m deep.', null, null, null),
  ('geography', 'hard', 'Which strait separates Asia from North America?', '["Strait of Malacca","Strait of Gibraltar","Bosporus","Bering Strait"]'::jsonb, 3, 'The Bering Strait lies between Russia''s Chukotka Peninsula and Alaska.', null, null, null),
  ('history', 'easy', 'In which year did World War II end?', '["1944","1946","1939","1945"]'::jsonb, 3, 'The war ended in 1945: in Europe in May and in Asia with Japan''s surrender in August/September.', null, null, null),
  ('history', 'easy', 'Who was the first President of the United States?', '["Thomas Jefferson","George Washington","Abraham Lincoln","John Adams"]'::jsonb, 1, 'George Washington served as the first President from 1789 to 1797.', null, null, null),
  ('history', 'easy', 'In which year did India gain independence from British rule?', '["1950","1942","1857","1947"]'::jsonb, 3, 'India became independent on 15 August 1947. It became a republic in 1950.', null, null, null),
  ('history', 'medium', 'Which civilisation built the citadel of Machu Picchu?', '["Aztec","Inca","Maya","Olmec"]'::jsonb, 1, 'Machu Picchu was built by the Inca in the 15th century in the Andes of present-day Peru.', null, null, null),
  ('history', 'medium', 'Who founded the Maurya Empire in ancient India?', '["Ashoka","Chandragupta Maurya","Bindusara","Bimbisara"]'::jsonb, 1, 'Chandragupta Maurya founded the empire around 322 BCE; Ashoka was his grandson.', null, null, null),
  ('history', 'medium', 'In which year did the Berlin Wall fall?', '["1989","1991","1987","1961"]'::jsonb, 0, 'The Berlin Wall was opened on 9 November 1989. It had been built in 1961.', null, null, null),
  ('history', 'hard', 'The Battle of Plassey (1757) was fought between the British East India Company and which ruler?', '["Tipu Sultan","Mir Jafar","Shah Alam II","Siraj ud-Daulah"]'::jsonb, 3, 'Robert Clive''s forces defeated Siraj ud-Daulah, the Nawab of Bengal, aided by the defection of Mir Jafar.', null, null, null),
  ('history', 'hard', 'Which treaty, signed in 1919, formally ended World War I between the Allied Powers and Germany?', '["Treaty of Westphalia","Treaty of Tordesillas","Treaty of Versailles","Treaty of Utrecht"]'::jsonb, 2, 'The Treaty of Versailles was signed on 28 June 1919. Westphalia (1648) ended the Thirty Years'' War.', null, null, null),
  ('indian_mythology', 'easy', 'In Hindu tradition, the Sanskrit epic Ramayana is traditionally attributed to which sage?', '["Vyasa","Kalidasa","Valmiki","Tulsidas"]'::jsonb, 2, 'Valmiki is traditionally credited with the Sanskrit Ramayana. Tulsidas later wrote the Awadhi retelling, Ramcharitmanas.', 'Hindu (Ramayana)', null, null),
  ('indian_mythology', 'easy', 'In the Mahabharata, who delivers the teachings of the Bhagavad Gita to Arjuna?', '["Bhishma","Drona","Krishna","Vidura"]'::jsonb, 2, 'The Bhagavad Gita is a dialogue between Krishna and Arjuna on the battlefield of Kurukshetra.', 'Hindu (Mahabharata)', null, null),
  ('indian_mythology', 'easy', 'Which deity in Hindu tradition is depicted with the head of an elephant?', '["Kartikeya","Ganesha","Hanuman","Indra"]'::jsonb, 1, 'Ganesha, son of Shiva and Parvati, is depicted with an elephant head and is revered as the remover of obstacles.', 'Hindu', null, null),
  ('indian_mythology', 'medium', 'In Hindu tradition, which divine bird serves as the mount (vahana) of Vishnu?', '["Garuda","Nandi","Airavata","Mushika"]'::jsonb, 0, 'Garuda is Vishnu''s vahana. Nandi is Shiva''s bull, Airavata is Indra''s elephant and Mushika is Ganesha''s mouse.', 'Hindu', null, null),
  ('indian_mythology', 'medium', 'In the Mahabharata, which Pandava brother was famed for his immense strength and his skill with the mace?', '["Nakula","Sahadeva","Yudhishthira","Bhima"]'::jsonb, 3, 'Bhima, the second Pandava, was renowned for his strength and fought with a mace (gada).', 'Hindu (Mahabharata)', null, null),
  ('indian_mythology', 'medium', 'According to Puranic accounts of the Samudra Manthana (churning of the ocean), which serpent was used as the churning rope?', '["Shesha","Kaliya","Vasuki","Takshaka"]'::jsonb, 2, 'The serpent king Vasuki was wound around Mount Mandara, which served as the churning rod.', 'Hindu (Puranas)', null, null),
  ('indian_mythology', 'hard', 'In the Mahabharata, who narrates the events of the Kurukshetra war to the blind king Dhritarashtra?', '["Vidura","Shakuni","Sanjaya","Kripa"]'::jsonb, 2, 'Sanjaya, granted divine sight by Vyasa, describes the war to Dhritarashtra.', 'Hindu (Mahabharata)', null, null),
  ('indian_mythology', 'hard', 'In the Ramayana, which brother of Ravana left Lanka and joined Rama''s side?', '["Kumbhakarna","Vibhishana","Indrajit","Khara"]'::jsonb, 1, 'Vibhishana counselled Ravana to return Sita, was rejected, and allied with Rama. Indrajit was Ravana''s son.', 'Hindu (Ramayana)', null, null),
  ('indian_mythology', 'hard', 'In Puranic Hindu cosmology, which of the four yugas is described as the current age?', '["Satya Yuga","Kali Yuga","Treta Yuga","Dvapara Yuga"]'::jsonb, 1, 'The Puranas describe a cycle of Satya, Treta, Dvapara and Kali yugas, with the present age being Kali Yuga.', 'Hindu (Puranas)', null, null),
  ('literature', 'easy', 'Who wrote the play "Romeo and Juliet"?', '["Christopher Marlowe","Charles Dickens","William Shakespeare","Geoffrey Chaucer"]'::jsonb, 2, 'Shakespeare wrote Romeo and Juliet in the mid-1590s.', null, null, null),
  ('literature', 'easy', 'Who wrote the "Harry Potter" book series?', '["J. R. R. Tolkien","Roald Dahl","J. K. Rowling","C. S. Lewis"]'::jsonb, 2, 'J. K. Rowling wrote the seven Harry Potter novels (1997–2007).', null, null, null),
  ('literature', 'medium', 'Who received the 1913 Nobel Prize in Literature, notably for the English "Gitanjali"?', '["Sarojini Naidu","Bankim Chandra Chatterjee","Rabindranath Tagore","Premchand"]'::jsonb, 2, 'Tagore was the first non-European to win the Nobel Prize in Literature.', null, null, null),
  ('literature', 'medium', 'Which novel opens with the line "Call me Ishmael."?', '["Treasure Island","The Old Man and the Sea","Moby-Dick","Robinson Crusoe"]'::jsonb, 2, 'Herman Melville''s Moby-Dick (1851) begins with ''Call me Ishmael.''', null, null, null),
  ('literature', 'medium', 'Who wrote the dystopian novel "Nineteen Eighty-Four"?', '["Aldous Huxley","Ray Bradbury","George Orwell","H. G. Wells"]'::jsonb, 2, 'George Orwell published Nineteen Eighty-Four in 1949. Huxley wrote Brave New World.', null, null, null),
  ('literature', 'hard', 'Who wrote "One Hundred Years of Solitude"?', '["Jorge Luis Borges","Mario Vargas Llosa","Isabel Allende","Gabriel García Márquez"]'::jsonb, 3, 'García Márquez published the novel in 1967; it is a landmark of magical realism.', null, null, null),
  ('literature', 'hard', 'In which language did Kalidasa compose "Abhijnanashakuntalam"?', '["Pali","Tamil","Sanskrit","Persian"]'::jsonb, 2, 'Kalidasa wrote the play in Sanskrit (with some characters speaking Prakrit, as was dramatic convention).', null, null, null),
  ('literature', 'hard', 'Who wrote the epic poem "Paradise Lost"?', '["John Donne","Edmund Spenser","William Blake","John Milton"]'::jsonb, 3, 'John Milton published Paradise Lost in 1667.', null, null, null),
  ('mathematics', 'easy', 'What is 12 × 12?', '["124","144","132","156"]'::jsonb, 1, '12 × 12 = 144, also called a gross.', null, null, null),
  ('mathematics', 'easy', 'What is the value of π rounded to two decimal places?', '["3.41","3.16","3.14","3.12"]'::jsonb, 2, 'π ≈ 3.14159…, which rounds to 3.14.', null, null, null),
  ('mathematics', 'easy', 'What is 15% of 200?', '["30","15","20","35"]'::jsonb, 0, '0.15 × 200 = 30.', null, null, null),
  ('mathematics', 'medium', 'What is the square root of 169?', '["12","14","17","13"]'::jsonb, 3, '13 × 13 = 169.', null, null, null),
  ('mathematics', 'medium', 'What is the sum of the interior angles of a triangle in Euclidean geometry?', '["90°","360°","270°","180°"]'::jsonb, 3, 'In Euclidean geometry the interior angles of any triangle add up to 180°.', null, null, null),
  ('mathematics', 'medium', 'What is the smallest prime number greater than 13?', '["15","19","14","17"]'::jsonb, 3, '14, 15 and 16 are composite; 17 is prime.', null, null, null),
  ('mathematics', 'hard', 'What is 7! (7 factorial)?', '["720","40320","2520","5040"]'::jsonb, 3, '7! = 7 × 6 × 5 × 4 × 3 × 2 × 1 = 5040.', null, null, null),
  ('mathematics', 'hard', 'What is the derivative of sin(x) with respect to x?', '["−cos(x)","−sin(x)","tan(x)","cos(x)"]'::jsonb, 3, 'd/dx sin(x) = cos(x).', null, null, null),
  ('mathematics', 'hard', 'How many diagonals does a convex hexagon have?', '["6","12","9","15"]'::jsonb, 2, 'An n-sided polygon has n(n−3)/2 diagonals: 6 × 3 / 2 = 9.', null, null, null),
  ('movies', 'easy', 'Who directed the 1993 film "Jurassic Park"?', '["James Cameron","Steven Spielberg","George Lucas","Ridley Scott"]'::jsonb, 1, 'Steven Spielberg directed Jurassic Park, based on Michael Crichton''s novel.', null, null, null),
  ('movies', 'easy', 'In Disney''s "The Lion King" (1994), what is the name of Simba''s father?', '["Scar","Rafiki","Mufasa","Zazu"]'::jsonb, 2, 'Mufasa is Simba''s father; Scar is his uncle.', null, null, null),
  ('movies', 'medium', 'In the 1975 Hindi film "Sholay", what is the name of the infamous dacoit villain?', '["Mogambo","Gabbar Singh","Shakaal","Kancha Cheena"]'::jsonb, 1, 'Gabbar Singh, played by Amjad Khan, is the villain of Sholay. Mogambo is from Mr. India (1987).', null, null, null),
  ('movies', 'medium', 'Who composed the score for the original "Star Wars" (1977)?', '["Hans Zimmer","Ennio Morricone","John Williams","Howard Shore"]'::jsonb, 2, 'John Williams composed the Star Wars score, which won the Academy Award for Best Original Score.', null, null, null),
  ('movies', 'medium', 'James Cameron''s 2009 film "Avatar" is set on which fictional moon?', '["Endor","Arrakis","LV-426","Pandora"]'::jsonb, 3, 'Avatar takes place on Pandora. Endor is from Star Wars, Arrakis from Dune and LV-426 from Alien.', null, null, null),
  ('movies', 'hard', 'Which film became the first non-English-language winner of the Academy Award for Best Picture (2020 ceremony)?', '["Roma","1917","Parasite","Joker"]'::jsonb, 2, 'Bong Joon-ho''s South Korean film Parasite won Best Picture at the 92nd Academy Awards in February 2020.', null, null, null),
  ('movies', 'hard', 'Which song from the film "RRR" won the Academy Award for Best Original Song in 2023?', '["Jai Ho","Komuram Bheemudo","Naatu Naatu","Dosti"]'::jsonb, 2, '''Naatu Naatu'', composed by M. M. Keeravani, won in March 2023. ''Jai Ho'' won in 2009 for Slumdog Millionaire.', null, null, null),
  ('movies', 'hard', 'Who directed the 1954 Japanese film "Seven Samurai"?', '["Akira Kurosawa","Yasujirō Ozu","Kenji Mizoguchi","Hayao Miyazaki"]'::jsonb, 0, 'Akira Kurosawa directed Seven Samurai, one of the most influential films ever made.', null, null, null),
  ('politics', 'easy', 'Which country hosted the G20 Leaders'' Summit in New Delhi in September 2023?', '["Indonesia","Brazil","India","Japan"]'::jsonb, 2, 'India held the G20 presidency in 2023 and hosted the summit on 9–10 September 2023.', null, '2023-09-10'::date, null),
  ('politics', 'easy', 'Who chaired the Drafting Committee of the Constituent Assembly of India?', '["Jawaharlal Nehru","Rajendra Prasad","Sardar Vallabhbhai Patel","B. R. Ambedkar"]'::jsonb, 3, 'Dr B. R. Ambedkar chaired the Drafting Committee. Rajendra Prasad presided over the Constituent Assembly.', null, '1949-11-26'::date, null),
  ('politics', 'medium', 'Which city hosted the 2024 Summer Olympic Games?', '["Los Angeles","Tokyo","Brisbane","Paris"]'::jsonb, 3, 'Paris hosted the Games from 26 July to 11 August 2024. Los Angeles is scheduled for 2028.', null, '2024-08-11'::date, null),
  ('politics', 'medium', 'In August 2023, which country''s Chandrayaan-3 mission made the first soft landing near the Moon''s south pole?', '["China","Japan","India","Russia"]'::jsonb, 2, 'ISRO''s Vikram lander touched down on 23 August 2023. Russia''s Luna-25 crashed days earlier.', null, '2023-08-23'::date, null),
  ('politics', 'medium', 'How many permanent members does the United Nations Security Council have?', '["10","15","5","6"]'::jsonb, 2, 'China, France, Russia, the UK and the US are the five permanent members; there are 15 members in total.', null, '2025-01-01'::date, null),
  ('politics', 'medium', 'Which union did the United Kingdom formally leave on 31 January 2020?', '["Commonwealth of Nations","NATO","European Union","Council of Europe"]'::jsonb, 2, 'Brexit took legal effect on 31 January 2020, followed by a transition period to 31 December 2020.', null, '2020-01-31'::date, null),
  ('politics', 'hard', 'Which organisation was admitted as a permanent member of the G20 at the September 2023 New Delhi summit?', '["ASEAN","Arab League","Mercosur","African Union"]'::jsonb, 3, 'The African Union joined as a permanent member in September 2023; the European Union was already a member.', null, '2023-09-09'::date, null),
  ('politics', 'hard', 'Which country became NATO''s 31st member in April 2023?', '["Sweden","Finland","Ukraine","Austria"]'::jsonb, 1, 'Finland joined on 4 April 2023. Sweden followed as the 32nd member in March 2024.', null, '2023-04-04'::date, null),
  ('politics', 'hard', 'On which date did the Constitution of India come into effect?', '["15 August 1947","26 November 1949","26 January 1950","2 October 1950"]'::jsonb, 2, 'The Constitution was adopted on 26 November 1949 and came into effect on 26 January 1950 (Republic Day).', null, '1950-01-26'::date, null),
  ('science', 'easy', 'Which gas do plants mainly absorb from the air for photosynthesis?', '["Carbon dioxide","Oxygen","Nitrogen","Hydrogen"]'::jsonb, 0, 'Plants take in carbon dioxide and, using light energy, produce glucose and release oxygen.', null, null, null),
  ('science', 'easy', 'What is the chemical symbol for gold?', '["Ag","Go","Au","Gd"]'::jsonb, 2, 'Au comes from the Latin ''aurum''. Ag is silver and Gd is gadolinium.', null, null, null),
  ('science', 'easy', 'Which planet is known as the Red Planet?', '["Venus","Jupiter","Mars","Mercury"]'::jsonb, 2, 'Iron oxide on its surface gives Mars its reddish appearance.', null, null, null),
  ('science', 'medium', 'In eukaryotic cells, which structure contains most of the cell''s genetic material?', '["Nucleus","Ribosome","Golgi apparatus","Cell membrane"]'::jsonb, 0, 'The nucleus houses chromosomal DNA. Mitochondria hold a small amount of their own DNA.', null, null, null),
  ('science', 'medium', 'What is the SI unit of electrical resistance?', '["Volt","Ampere","Watt","Ohm"]'::jsonb, 3, 'Resistance is measured in ohms (Ω); volts measure potential difference, amperes current, watts power.', null, null, null),
  ('science', 'medium', 'What is the approximate speed of light in a vacuum?', '["About 300,000 km per second","About 30,000 km per second","About 3,000,000 km per second","About 150,000 km per second"]'::jsonb, 0, 'Light travels at exactly 299,792,458 m/s in a vacuum, roughly 300,000 km/s.', null, null, null),
  ('science', 'hard', 'Which element has the highest electronegativity on the Pauling scale?', '["Oxygen","Chlorine","Fluorine","Nitrogen"]'::jsonb, 2, 'Fluorine has a Pauling electronegativity of about 3.98, the highest of all elements.', null, null, null),
  ('science', 'hard', 'Absolute zero (0 kelvin) is equal to which temperature in degrees Celsius?', '["−459.67 °C","−100 °C","−373.15 °C","−273.15 °C"]'::jsonb, 3, '0 K is defined as −273.15 °C. −459.67 is the Fahrenheit value.', null, null, null),
  ('sports', 'easy', 'How many players from one team are on the field at a time in association football (soccer)?', '["11","10","9","12"]'::jsonb, 0, 'Each side fields 11 players, including the goalkeeper.', null, null, null),
  ('sports', 'easy', 'In which sport is a score of zero called "love"?', '["Badminton","Tennis","Golf","Squash"]'::jsonb, 1, 'Tennis uses ''love'' for zero, as in ''fifteen-love''.', null, null, null),
  ('sports', 'easy', 'How many interlocking rings appear on the Olympic flag?', '["4","5","6","7"]'::jsonb, 1, 'The five rings represent the union of the five inhabited continents as conceived in the Olympic movement.', null, null, null),
  ('sports', 'medium', 'Which country won the first FIFA World Cup in 1930?', '["Uruguay","Brazil","Argentina","Italy"]'::jsonb, 0, 'Hosts Uruguay beat Argentina 4–2 in the 1930 final in Montevideo.', null, null, null),
  ('sports', 'medium', 'How many legal deliveries make up a standard over in cricket?', '["5","8","4","6"]'::jsonb, 3, 'A standard over consists of six legal deliveries.', null, null, null),
  ('sports', 'medium', 'In which city were the first modern Olympic Games held in 1896?', '["Athens","Paris","London","Rome"]'::jsonb, 0, 'The 1896 Games in Athens were the first of the modern Olympic era.', null, null, null),
  ('sports', 'hard', 'Who was the first batter to score a double century in a men''s One Day International?', '["Virender Sehwag","Rohit Sharma","Chris Gayle","Sachin Tendulkar"]'::jsonb, 3, 'Tendulkar scored 200* against South Africa in Gwalior in February 2010. Belinda Clark had made the first women''s ODI 200 in 1997.', null, null, null),
  ('sports', 'hard', 'What is the official distance of a marathon?', '["40 km","41.195 km","45 km","42.195 km"]'::jsonb, 3, 'The marathon distance was standardised at 42.195 km (26 miles 385 yards) in 1921.', null, null, null),
  ('technology', 'easy', 'What does CPU stand for?', '["Central Program Utility","Computer Power Unit","Central Processing Unit","Core Processing Utility"]'::jsonb, 2, 'The CPU is the Central Processing Unit that executes program instructions.', null, null, null),
  ('technology', 'easy', 'What does HTML stand for?', '["High Transfer Machine Language","HyperText Media Link","Home Tool Markup Language","HyperText Markup Language"]'::jsonb, 3, 'HTML, HyperText Markup Language, structures content on the web.', null, null, null),
  ('technology', 'easy', 'How many bits make up one byte?', '["8","4","16","10"]'::jsonb, 0, 'In modern computing a byte is 8 bits.', null, null, null),
  ('technology', 'medium', 'Which programming language was created by Guido van Rossum?', '["Python","Ruby","Java","Perl"]'::jsonb, 0, 'Guido van Rossum released Python in 1991. Ruby is by Yukihiro Matsumoto, Java by James Gosling, Perl by Larry Wall.', null, null, null),
  ('technology', 'medium', 'Which data structure follows the Last-In, First-Out (LIFO) principle?', '["Queue","Stack","Linked list","Hash table"]'::jsonb, 1, 'A stack removes the most recently added item first. A queue is First-In, First-Out.', null, null, null),
  ('technology', 'medium', 'What is the default TCP port for HTTPS?', '["80","21","443","8080"]'::jsonb, 2, 'HTTPS uses port 443 by default; plain HTTP uses 80 and FTP uses 21.', null, null, null),
  ('technology', 'hard', 'What is the worst-case time complexity of binary search on a sorted array of n elements?', '["O(n)","O(n log n)","O(log n)","O(1)"]'::jsonb, 2, 'Binary search halves the search space every step, taking O(log n) comparisons.', null, null, null),
  ('technology', 'hard', 'Who wrote what is widely regarded as the first published algorithm intended for Charles Babbage''s Analytical Engine?', '["Grace Hopper","Alan Turing","Charles Babbage","Ada Lovelace"]'::jsonb, 3, 'In 1843 Ada Lovelace published notes including an algorithm to compute Bernoulli numbers on the Analytical Engine.', null, null, null),
  ('technology', 'hard', 'In networking, what does DNS primarily do?', '["Encrypts web traffic","Assigns MAC addresses to devices","Compresses network packets","Translates domain names into IP addresses"]'::jsonb, 3, 'The Domain Name System resolves human-readable names like example.com to IP addresses.', null, null, null),
  ('world_mythology', 'easy', 'In Greek mythology, who is the king of the gods, ruling from Mount Olympus?', '["Poseidon","Zeus","Hades","Apollo"]'::jsonb, 1, 'Zeus rules Olympus; his brothers Poseidon and Hades rule the sea and the underworld.', 'Greek', null, null),
